import ast
import os
import sys
import subprocess
import tempfile
import shutil
import tomllib
import re
import time
import unittest
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define fallbacks
try:
    from hae.evaluation.artifacts import (
        is_generated_path, 
        is_malformed_path, 
        filter_bundle, 
        count_source_files
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if '*' in path or '`' in path:
            return True
        if path != path.strip():
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in filter_bundle(bundle):
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "PASS" if g.passed else ("SKIP" if g.status == SKIPPED else "FAIL")
            lines.append(f"[{status_icon}] {g.name}: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```[lang] [filename]\n...\n```
    # We look for lines that look like paths in the fence info string
    pattern = r"```(?:\w+)?\s+([^\n]+)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for path_hint, content in matches:
        # Clean up the path hint
        path = path_hint.strip()
        # Remove potential markdown formatting from path
        path = path.replace('`', '').replace('*', '').strip()

        # Basic validation: must look like a file path
        if not path or path.startswith('-') or path.endswith('.') or path.endswith('~'):
            continue

        # If the path doesn't have an extension, we might guess, but usually it should
        # We only care about .py files for the gates, but we store all valid paths
        if path not in bundle:
            bundle[path] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        clean_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(clean_bundle)
        python_files = count_source_files(clean_bundle, ('.py',))

        # Create temp dir
        tmp_dir = tempfile.mkdtemp(prefix="hae_verify_")
        try:
            # Write files
            for path, content in clean_bundle.items():
                full_path = os.path.join(tmp_dir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmp_dir, authored=clean_bundle, source=source)
        finally:
            shutil.rmtree(tmp_dir, ignore_errors=True)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, ('.py',))

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, authored))

        # Gate 2: Build
        gates.append(self._gate_build(workdir, authored))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, authored))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, authored))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found.',
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail=f"Syntax errors in {len(errors)} files: {errors[0]}",
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail=f"All {len(py_files)} Python files parsed successfully.",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found.',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='toml_validation',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool]).',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='toml_validation',
                    detail=f'Failed to parse pyproject.toml: {e}',
                    duration_s=time.time() - start
                )

        # Attempt pip install
        pip_cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            result = subprocess.run(
                pip_cmd,
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode != 0:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stdout': result.stdout, 'stderr': result.stderr}
                )

            return GateResult(
                name='build',
                status=PASSED,
                method='pip_install',
                detail='Package installed successfully.',
                duration_s=duration
            )

        except FileNotFoundError:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available.',
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out.',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error running pip: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # Exclude test files
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # e.g., src/foo/bar.py -> foo.bar (if src is on path)
            # We will try to import the file directly or via module path

            # Determine module name relative to workdir or src
            rel_path = path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            if rel_path.endswith('.py'):
                module_name = rel_path[:-3].replace('/', '.').replace('\\', '.')
                if module_name:
                    modules.append((path, module_name))

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found.',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        env = os.environ.copy()
        python_path = [workdir, os.path.join(workdir, 'src')]
        if 'PYTHONPATH' in env:
            python_path.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try importing each module in a subprocess
        failures = []
        skipped_third_party = False

        for path, module_name in modules:
            # Script to import the module
            script = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', script],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    # Check for ModuleNotFoundError for third-party packages
                    if 'ModuleNotFoundError' in stderr:
                        # Heuristic: if the missing module is not in our authored files, it's third-party
                        # Extract missing module name
                        match = re.search(r"No module named '([^']+)'", stderr)
                        if match:
                            missing_mod = match.group(1)
                            # Check if missing_mod is part of our authored modules
                            is_authored = any(m.startswith(missing_mod) or missing_mod.startswith(m) for _, m in modules)
                            if not is_authored:
                                skipped_third_party = True
                                continue

                    failures.append(f"{module_name}: {stderr.strip()}")

            except subprocess.TimeoutExpired:
                failures.append(f"{module_name}: Timeout")
            except Exception as e:
                failures.append(f"{module_name}: {e}")

        duration = time.time() - start

        if failures:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail=f"Import failures: {failures[0]}",
                duration_s=duration,
                evidence={'failures': failures}
            )

        if skipped_third_party:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Imports skipped due to missing third-party dependencies.',
                duration_s=duration
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(modules)} modules imported successfully.",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='test_discovery',
                detail='No test files found.',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        env = os.environ.copy()
        python_path = [workdir, os.path.join(workdir, 'src')]
        if 'PYTHONPATH' in env:
            python_path.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Check if pytest is available
        pytest_available = False
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            pytest_available = True
        except Exception:
            pass

        if pytest_available:
            # Run pytest
            cmd = [self.python_executable, '-m', 'pytest', '-v'] + test_files
            try:
                result = subprocess.run(
                    cmd,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed.',
                        duration_s=duration
                    )
                else:
                    # Check if failure was due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                         # Heuristic: if it's a collection error due to missing deps
                         if 'error' in result.stderr.lower() and 'module' in result.stderr.lower():
                             return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest',
                                detail='Tests skipped due to missing dependencies.',
                                duration_s=duration
                            )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f'Tests failed. Exit code: {result.returncode}',
                        duration_s=duration,
                        evidence={'stdout': result.stdout, 'stderr': result.stderr}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out.',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Error running pytest: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # We need to run a script that imports each test file and runs tests
            # This is complex to do in a single subprocess call robustly.
            # We'll write a temporary runner script.

            runner_script = """
