import os
import unittest
import importlib.util

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for test_file in test_files:
        try:
            # Add directory to path
            dir_name = os.path.dirname(test_file)
            if dir_name not in sys.path:
                sys.path.insert(0, dir_name)

            # Import module
            module_name = os.path.basename(test_file).replace('.py', '')
            spec = importlib.util.spec_from_file_location(module_name, test_file)
            if spec is None:
                continue
            module = importlib.util.module_from_spec(spec)
            sys.modules[module_name] = module
            spec.loader.exec_module(module)

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase):
                    suite.addTests(loader.loadTestsFromTestCase(obj))

            # Collect bare test_* functions
            for name in dir(module):
                if name.startswith('test_'):
                    obj = getattr(module, name)
                    if callable(obj) and not isinstance(obj, type):
                        # Check if it takes 0 required args
                        import inspect
                        sig = inspect.signature(obj)
                        params = [p for p in sig.parameters.values() if p.default is inspect.Parameter.empty]
                        if len(params) == 0:
                            suite.addTest(unittest.FunctionTestCase(obj))

        except Exception as e:
            print(f"Error loading {test_file}: {e}", file=sys.stderr)
            # If it's a ModuleNotFoundError, we might want to skip
            if 'ModuleNotFoundError' in str(e):
                print("MODULE_NOT_FOUND_ERROR", file=sys.stderr)
                sys.exit(2) # Special exit code for skip

    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)

    if result.wasSuccessful():
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    test_files = sys.argv[1:]
    run_tests(test_files)
"""
            runner_path = os.path.join(workdir, '_hae_test_runner.py')
            with open(runner_path, 'w') as f:
                f.write(runner_script)

            try:
                cmd = [self.python_executable, runner_path] + test_files
                result = subprocess.run(
                    cmd,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='stdlib_fallback',
                        detail='All tests passed.',
                        duration_s=duration
                    )
                elif result.returncode == 2:
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='stdlib_fallback',
                        detail='Tests skipped due to missing dependencies.',
                        duration_s=duration
                    )
                else:
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib_fallback',
                        detail=f'Tests failed. Exit code: {result.returncode}',
                        duration_s=duration,
                        evidence={'stdout': result.stdout, 'stderr': result.stderr}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib_fallback',
                    detail='Tests timed out.',
                    duration_s=time.time() - start
                )
            except Exception as e:
