    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No Python files to analyze.',
                duration_s=time.time() - start
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 
            'start_span', 
